use vstd::prelude::*;
use vstd::vec::Vec;
use vstd::seq::Seq;

verus! {
    /// In‐place replacement of occurrences of `x` with `y` in the vector `v`.
    /// 
    /// Postcondition:
    ///   1. The length of `v` is unchanged.
    ///   2. For each index `k` in `[0, old_len)`,
    ///      - if `old_v[k] == x` then `v[k] == y`,
    ///      - otherwise         `v[k] == old_v[k]`.
    pub fn replace(v: &mut Vec<i32>, x: i32, y: i32)
        ensures
            // Length is unchanged
            v.len() == old(v.len()) &&
            // Each element is either unchanged or replaced as specified
            forall |k: usize| k < old(v.len()) ==>
                if old(v@)[k] == x {
                    v@[k] == y
                } else {
                    v@[k] == old(v@)[k]
                }
    {
        // Snapshot of the original contents
        let old_v: Seq<i32> = v@;
        let len: usize = old_v.len();

        let mut i: usize = 0;
        while i < len
            invariant
                // Loop index remains in bounds
                i <= len &&
                // The vector’s length never changes
                v.len() == len &&
                // For all processed indices < i, we've done the correct replacement
                forall |k: usize| k < i ==>
                    if old_v[k] == x {
                        v@[k] == y
                    } else {
                        v@[k] == old_v[k]
                    }
            decreases len - i
        {
            if v[i] == x {
                v[i] = y;
            }
            i += 1;
        }
    }
}